import{_ as t,o as s,c as e,a2 as n}from"./chunks/framework.C4u7U0Dw.js";const u=JSON.parse('{"title":"第 13 章 知识管理：让记忆可复用","description":"","frontmatter":{},"headers":[],"relativePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md","filePath":"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md"}'),o={name:"bluebook/第二篇 案例篇：从一项任务到一支 AI 团队/第 13 章 知识管理：让记忆可复用.md"};function i(l,a,p,d,r,h){return s(),e("div",null,[...a[0]||(a[0]=[n(`<h1 id="第-13-章-知识管理-让记忆可复用" tabindex="-1">第 13 章 知识管理：让记忆可复用 <a class="header-anchor" href="#第-13-章-知识管理-让记忆可复用" aria-label="Permalink to &quot;第 13 章 知识管理：让记忆可复用&quot;">​</a></h1><h2 id="_13-1-场景" tabindex="-1">13.1 场景 <a class="header-anchor" href="#_13-1-场景" aria-label="Permalink to &quot;13.1 场景&quot;">​</a></h2><p>你收集了很多资料：文章、笔记、代码片段、会议纪要。但&quot;收藏了 = 拥有了&quot;是错觉——真正的问题是：<strong>要用的时候，找不找得到、用不用得上。</strong></p><p>知识管理的目标不是&quot;存得多&quot;，而是<strong>让知识在需要时能被调出来、用起来</strong>。</p><h2 id="_13-2-知识管理的三个层次" tabindex="-1">13.2 知识管理的三个层次 <a class="header-anchor" href="#_13-2-知识管理的三个层次" aria-label="Permalink to &quot;13.2 知识管理的三个层次&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层次</th><th>问题</th><th>我的角色</th></tr></thead><tbody><tr><td>存</td><td>资料放哪、怎么命名</td><td>帮你建立可检索的结构</td></tr><tr><td>找</td><td>需要时能否快速找到</td><td>Glob/Grep 精准定位</td></tr><tr><td>用</td><td>找到后能否变成产出</td><td>提炼、总结、复用</td></tr></tbody></table><h2 id="_13-3-案例-把收藏夹变成知识库" tabindex="-1">13.3 案例：把收藏夹变成知识库 <a class="header-anchor" href="#_13-3-案例-把收藏夹变成知识库" aria-label="Permalink to &quot;13.3 案例：把收藏夹变成知识库&quot;">​</a></h2><p><strong>指令：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>我 docs/notes/ 里有一堆零散笔记，帮我：</span></span>
<span class="line"><span>1. 扫描并分类（按主题归入 ai/、marketing/、engineering/ 等）</span></span>
<span class="line"><span>2. 为每篇生成 3 行的摘要 + 标签（frontmatter）</span></span>
<span class="line"><span>3. 输出一份索引表 notes_index.md</span></span></code></pre></div><p><strong>我的做法：</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Glob 列出全部笔记 → 逐个 Read 提炼摘要 → 重命名/归类</span></span>
<span class="line"><span>→ 写索引 → 你抽查摘要质量 → 入库</span></span></code></pre></div><h2 id="_13-4-提炼-从资料到知识" tabindex="-1">13.4 提炼：从资料到知识 <a class="header-anchor" href="#_13-4-提炼-从资料到知识" aria-label="Permalink to &quot;13.4 提炼：从资料到知识&quot;">​</a></h2><p>知识管理的核心动作是<strong>提炼</strong>。我会帮你把一篇长文变成：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>一句话结论 + 3 个要点 + 适用范围 + 可执行动作</span></span></code></pre></div><p>例：&quot;这篇文章讲结构化提示词 → 结论：给 AI 任务要带验收标准 → 要点：目标/输入/约束/验收 → 适用：所有 AI 任务 → 动作：用第 2 章模板&quot;</p><h2 id="_13-5-让知识-长-进记忆" tabindex="-1">13.5 让知识&quot;长&quot;进记忆 <a class="header-anchor" href="#_13-5-让知识-长-进记忆" aria-label="Permalink to &quot;13.5 让知识&quot;长&quot;进记忆&quot;">​</a></h2><p>稳定的知识（你的方法论、常用模板、项目决策）应该<strong>进入记忆系统</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&quot;把这个提示词模板存进记忆，以后写方案默认用它。&quot;</span></span></code></pre></div><p>而具体的资料文件留在项目里。这样：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>记忆 = 方法论（怎么做）</span></span>
<span class="line"><span>文件 = 素材库（有什么）</span></span></code></pre></div><h2 id="_13-6-知识管理的红线" tabindex="-1">13.6 知识管理的红线 <a class="header-anchor" href="#_13-6-知识管理的红线" aria-label="Permalink to &quot;13.6 知识管理的红线&quot;">​</a></h2><ul><li><strong>先确认再入库</strong>：摘要、分类、标签先给你看；</li><li><strong>不破坏原文件</strong>：归类用复制或移动前先确认；</li><li><strong>敏感资料标注</strong>：涉及隐私/机密的资料，明确访问范围。</li></ul><h2 id="_13-7-练习" tabindex="-1">13.7 练习 <a class="header-anchor" href="#_13-7-练习" aria-label="Permalink to &quot;13.7 练习&quot;">​</a></h2><ol><li>给我一个装满资料的目录，让我做&quot;分类 + 摘要 + 索引&quot;；</li><li>抽查 3 篇摘要，反馈我提炼得准不准；</li><li>把其中一条方法论存入记忆。</li></ol><blockquote><p>小结：知识管理不是整理文件，而是<strong>让过去的投入，在未来的任务里再次变现</strong>。</p></blockquote>`,25)])])}const b=t(o,[["render",i]]);export{u as __pageData,b as default};
